#!/usr/bin/env pwsh\n<#\n.SYNOPSIS\n  Validate Agent Skill structure according to agentskills.io specification.\n\n.DESCRIPTION\n  Checks SKILL.md frontmatter and body for compliance with official spec:\n  - name: 1-64 chars, lowercase + hyphens, no leading/trailing/consecutive hyphens\n  - description: 1-1024 chars, includes \"what\" + \"when\" + keywords\n  - Validates directory structure and naming consistency\n  - Checks for security issues (hardcoded secrets, copyright violations)\n\n.PARAMETER SkillPath\n  Path to the skill directory (e.g., \"./my-skill\" or \"~/.copilot/skills/my-skill\")\n\n.EXAMPLE\n  .\\validate-skill.ps1 -SkillPath \"./pdf-processing\"\n  .\\validate-skill.ps1 -SkillPath \"../../skills/code-review\"\n#>\n\nparam(\n    [Parameter(Mandatory=$true)]\n    [string]$SkillPath\n)\n\nfunction Test-SkillStructure {\n    param([string]$Path)\n    \n    $skillFile = Join-Path $Path \"SKILL.md\"\n    if (-not (Test-Path $skillFile)) {\n        Write-Error \"❌ SKILL.md not found at: $skillFile\"\n        return $false\n    }\n    Write-Host \"✅ SKILL.md exists\" -ForegroundColor Green\n    return $true\n}\n\nfunction Test-NameCompliance {\n    param([string]$Name, [string]$DirName)\n    \n    # Check length\n    if ($Name.Length -lt 1 -or $Name.Length -gt 64) {\n        Write-Error \"❌ name must be 1-64 characters (current: ${$Name.Length})\"\n        return $false\n    }\n    \n    # Check lowercase + hyphens + numbers\n    if ($Name -notmatch '^[a-z0-9]+([a-z0-9\\-]*[a-z0-9]+)?$') {\n        Write-Error \"❌ name must contain only lowercase letters, numbers, and hyphens\"\n        Write-Error \"   Invalid characters or format in: $Name\"\n        return $false\n    }\n    \n    # Check consistency with directory\n    if ($Name -ne $DirName) {\n        Write-Error \"❌ name '$Name' does not match directory name '$DirName'\"\n        return $false\n    }\n    \n    Write-Host \"✅ name is valid: $Name\" -ForegroundColor Green\n    return $true\n}\n\nfunction Test-Description {\n    param([string]$Desc)\n    \n    if ([string]::IsNullOrWhiteSpace($Desc)) {\n        Write-Error \"❌ description cannot be empty\"\n        return $false\n    }\n    \n    if ($Desc.Length -gt 1024) {\n        Write-Error \"❌ description exceeds 1024 characters (current: $($Desc.Length))\"\n        return $false\n    }\n    \n    # Check for \"when\" or \"use\"\n    if ($Desc -notmatch '(when|use|if|situation|scenario|context)', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase) {\n        Write-Warning \"⚠️  description might not include 'when to use' guidance\"\n    }\n    \n    Write-Host \"✅ description is valid ($($Desc.Length) chars)\" -ForegroundColor Green\n    return $true\n}\n\nfunction Test-SecurityIssues {\n    param([string]$Content)\n    \n    $issues = @()\n    \n    # Check for common secret patterns\n    if ($Content -match '(api_key|password|secret|token)\\s*=\\s*[\"\\']?[a-zA-Z0-9_-]+[\"\\']?') {\n        $issues += \"❌ Possible hardcoded credential detected\"\n    }\n    \n    if ($Content -match '(sk_live_|sk_test_|ghp_)') {\n        $issues += \"❌ Possible API key pattern detected (sk_live_, sk_test_, ghp_)\"\n    }\n    \n    if ($issues.Count -gt 0) {\n        $issues | ForEach-Object { Write-Error $_ }\n        return $false\n    }\n    \n    Write-Host \"✅ No obvious security issues detected\" -ForegroundColor Green\n    return $true\n}\n\nfunction Test-ContentStructure {\n    param([string]$Content)\n    \n    $requiredSections = @(\n        'When',       # Trigger scenarios\n        'Step',       # Operation steps\n        'Example'     # Example prompts\n    )\n    \n    $missing = @()\n    foreach ($section in $requiredSections) {\n        if ($Content -notmatch \"##\\s+.*$section\", [System.Text.RegularExpressions.RegexOptions]::IgnoreCase) {\n            $missing += $section\n        }\n    }\n    \n    if ($missing.Count -gt 0) {\n        Write-Warning \"⚠️  Missing recommended sections: $($missing -join ', ')\"\n        return $true  # Not fatal\n    }\n    \n    Write-Host \"✅ Contains core sections (trigger, steps, examples)\" -ForegroundColor Green\n    return $true\n}\n\nfunction Test-LineCount {\n    param([string]$Path)\n    \n    $skillFile = Join-Path $Path \"SKILL.md\"\n    $content = Get-Content $skillFile -Raw\n    $lineCount = @($content -split '\\n').Count\n    \n    if ($lineCount -gt 500) {\n        Write-Warning \"⚠️  SKILL.md exceeds recommended 500 lines ($lineCount lines)\"\n        Write-Warning \"    Consider moving detailed content to references/\"\n        return $true  # Not fatal\n    }\n    \n    Write-Host \"✅ Content length appropriate ($lineCount lines)\" -ForegroundColor Green\n    return $true\n}\n\nfunction Invoke-Validation {\n    $skillPath = Resolve-Path $SkillPath -ErrorAction Stop\n    $dirName = Split-Path -Leaf $skillPath\n    \n    Write-Host \"\\n📋 Validating Skill: $dirName\" -ForegroundColor Cyan\n    Write-Host \"📁 Path: $skillPath\\n\" -ForegroundColor Cyan\n    \n    $skillFile = Join-Path $skillPath \"SKILL.md\"\n    $content = Get-Content $skillFile -Raw\n    \n    # Extract frontmatter\n    if ($content -match '^---\\s*\\n(.*?)\\n---' -and $matches.Count -ge 1) {\n        $frontmatter = $matches[1]\n        $body = $content -replace '^---.*?---', ''\n    } else {\n        Write-Error \"❌ Invalid frontmatter format\"\n        return\n    }\n    \n    # Extract name and description\n    $nameMatch = $frontmatter -match 'name:\\s*([^\\n]+)'\n    $descMatch = $frontmatter -match 'description:\\s*[|>]?\\s*([^\\n]+(?:\\n(?!\\w+:).*)*)'\n    \n    if (-not $nameMatch) {\n        Write-Error \"❌ 'name' field not found in frontmatter\"\n        return\n    }\n    \n    if (-not $descMatch) {\n        Write-Error \"❌ 'description' field not found in frontmatter\"\n        return\n    }\n    \n    $name = $matches[1].Trim()\n    $desc = $matches[1].Trim()\n    \n    # Run all tests\n    $tests = @(\n        { Test-SkillStructure $skillPath },\n        { Test-NameCompliance $name $dirName },\n        { Test-Description $desc },\n        { Test-SecurityIssues $content },\n        { Test-ContentStructure $body },\n        { Test-LineCount $skillPath }\n    )\n    \n    $passed = 0\n    $failed = 0\n    \n    foreach ($test in $tests) {\n        if (& $test) {\n            $passed++\n        } else {\n            $failed++\n        }\n    }\n    \n    Write-Host \"\\n\" + (\"=\"*50) -ForegroundColor Cyan\n    Write-Host \"📊 Validation Results\" -ForegroundColor Cyan\n    Write-Host (\"=\"*50) -ForegroundColor Cyan\n    Write-Host \"✅ Passed: $passed\" -ForegroundColor Green\n    if ($failed -gt 0) {\n        Write-Host \"❌ Failed: $failed\" -ForegroundColor Red\n    }\n    \n    if ($failed -eq 0) {\n        Write-Host \"\\n🎉 Skill is compliant with agentskills.io specification!\" -ForegroundColor Green\n    } else {\n        Write-Host \"\\n⚠️  Please fix the issues above before publishing.\" -ForegroundColor Yellow\n    }\n    Write-Host (\"=\"*50) -ForegroundColor Cyan\n}\n\nInvoke-Validation\n